    /// chains up through.
    /// </summary>
    /// <param name="instance">The native <c>GstBaseParse</c>.</param>
    /// <returns>The parent class of the managed subclass.</returns>
    private static Gst.Base.BaseParseClassRaw* ParentClassOf(nint instance) =>
        (Gst.Base.BaseParseClassRaw*)Gst.GObject.SubclassRegistry.DescriptorFor(instance).ParentClass;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int StartTrampoline(nint parse)
    {
        try
        {
            if (Gst.GObject.Object.TryGetInterned(parse) is not BaseParse managed)
            {
                return (ChainUpStart(parse)) ? 1 : 0;
            }

            return (managed.OnStart()) ? 1 : 0;
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return default;
        }
    }

