    private static nint GetSinkCapsTrampoline(nint parse, nint filter)
    {
        try
        {
            if (Gst.GObject.Object.TryGetInterned(parse) is not BaseParse managed)
            {
                return ChainUpGetSinkCaps(parse, filter);
            }

            using Gst.Caps? filterValue = filter == nint.Zero ? null : Gst.Caps.Borrow(filter);
            Gst.Caps? result = managed.OnGetSinkCaps(filterValue!);
            if (result is null)
